<!-- wp:wdl/lw-pr-step-7 {"circleBgColor":"#8a5a2b","cardBgColor":"#ffffff","borderColor":"#e2d9cc","ulMaxWidth":1080,"columnCountPc":4,"columnCountSp":1,"fontSizeClass":"font_size_m","fontWeightNo":"700","colorNo":"#ffffff","titleTag":"h3","fontWeightH3":"600","colorH3":"#2b2724","colorP":"#3a352f"} -->
<div class="wp-block-wdl-lw-pr-step-7 lw-pr-step-7 font_size_m"><ul class="lw-pr-step-7__inner" style="max-width:1080px;--column-pc:4;--column-sp:1"><li class="lw-pr-step-7__li" style="background-color:#ffffff;border-color:#e2d9cc"><div class="lw-pr-step-7__li_no" data-lw_font_set="Murecho" style="font-weight:700;background-color:#8a5a2b;color:#ffffff">1</div><div class="lw-pr-step-7__li_in"><h3 class="lw-pr-step-7__li_title ttl" data-lw_font_set="" style="font-weight:600;color:#2b2724">西口を出る</h3><p class="lw-pr-step-7__li_text" data-lw_font_set="" style="font-weight:400;color:#3a352f">改札はひとつだけです。出たらそのまま正面の階段を降ります。東口に出ると反対側なのでご注意ください。</p></div></li><li class="lw-pr-step-7__li" style="background-color:#ffffff;border-color:#e2d9cc"><div class="lw-pr-step-7__li_no" data-lw_font_set="Murecho" style="font-weight:700;background-color:#8a5a2b;color:#ffffff">2</div><div class="lw-pr-step-7__li_in"><h3 class="lw-pr-step-7__li_title ttl" data-lw_font_set="" style="font-weight:600;color:#2b2724">交差点を左へ</h3><p class="lw-pr-step-7__li_text" data-lw_font_set="" style="font-weight:400;color:#3a352f">階段を降りて30mほど直進すると、コンビニのある交差点に出ます。そこを左に曲がります。</p></div></li><li class="lw-pr-step-7__li" style="background-color:#ffffff;border-color:#e2d9cc"><div class="lw-pr-step-7__li_no" data-lw_font_set="Murecho" style="font-weight:700;background-color:#8a5a2b;color:#ffffff">3</div><div class="lw-pr-step-7__li_in"><h3 class="lw-pr-step-7__li_title ttl" data-lw_font_set="" style="font-weight:600;color:#2b2724">花屋を過ぎる</h3><p class="lw-pr-step-7__li_text" data-lw_font_set="" style="font-weight:400;color:#3a352f">ゆるい上り坂を2分ほど。右手に赤いひさしの花屋さんが見えたら、道は合っています。</p></div></li><li class="lw-pr-step-7__li" style="background-color:#ffffff;border-color:#e2d9cc"><div class="lw-pr-step-7__li_no" data-lw_font_set="Murecho" style="font-weight:700;background-color:#8a5a2b;color:#ffffff">4</div><div class="lw-pr-step-7__li_in"><h3 class="lw-pr-step-7__li_title ttl" data-lw_font_set="" style="font-weight:600;color:#2b2724">白いビルの2階</h3><p class="lw-pr-step-7__li_text" data-lw_font_set="" style="font-weight:400;color:#3a352f">花屋から50m先、白い3階建ての建物です。外階段を上がった2階が当店です。</p></div></li></ul></div>
<!-- /wp:wdl/lw-pr-step-7 -->
